<template><ContentWrap><div class="mb-16px"><el-button type="primary" v-hasPermi="['zsjos:gift-config:create']" @click="open()">新增礼品节点</el-button><el-button @click="load">刷新</el-button></div><el-tree v-loading="loading" :data="tree" node-key="id" default-expand-all><template #default="{ data }"><span class="flex justify-between w-full"><span>{{ data.name }} <el-tag size="small" type="info">{{ data.code }}</el-tag></span><span><el-tag size="small" :type="data.status === 0 ? 'success' : 'info'">{{ data.status === 0 ? '启用' : '停用' }}</el-tag><el-button link @click.stop="open(data)">编辑</el-button><el-button link type="danger" @click.stop="remove(data)">删除</el-button></span></span></template></el-tree><el-empty v-if="!loading && !tree.length" description="暂无礼品配置"/><el-dialog v-model="dialog" :title="form.id ? '编辑礼品节点' : '新增礼品节点'"><el-form ref="formRef" :model="form" label-width="90px"><el-form-item label="名称" prop="name" required><el-input v-model="form.name"/></el-form-item><el-form-item label="编码" prop="code" required><el-input v-model="form.code"/></el-form-item><el-form-item label="父节点"><el-tree-select v-model="form.parentId" :data="tree" clearable check-strictly node-key="id" :props="{ label: 'name', value: 'id' }"/></el-form-item><el-form-item label="状态"><el-switch v-model="enabled"/></el-form-item><el-form-item label="排序"><el-input-number v-model="form.sort" :min="0"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></ContentWrap></template>
<script setup lang="ts">import { ref, reactive, computed, onMounted } from 'vue'; import { ElMessage, ElMessageBox } from 'element-plus'; import { getGiftConfigList, createGiftConfig, updateGiftConfig, deleteGiftConfig, type GiftConfigVO } from '@/api/zsjos/gift'; const loading=ref(false), dialog=ref(false), tree=ref<GiftConfigVO[]>([]); const form=reactive<any>({}); const enabled=computed({ get:()=>form.status===0, set:(v:boolean)=>{form.status=v?0:1} }); const load=async()=>{loading.value=true; try{ const r:any=await getGiftConfigList(); tree.value=r.data||r||[] } finally{loading.value=false} }; const open=(row?:GiftConfigVO)=>{Object.assign(form,row||{id:undefined,parentId:undefined,name:'',code:'',status:0,sort:0});dialog.value=true}; const save=async()=>{try{form.id?await updateGiftConfig(form):await createGiftConfig(form);ElMessage.success('保存成功');dialog.value=false;load()}catch(e){}}; const remove=async(row:GiftConfigVO)=>{await ElMessageBox.confirm(`确认删除「${row.name}」？`,'提示');await deleteGiftConfig(row.id);ElMessage.success('已删除');load()}; onMounted(load)</script>
